<script lang="ts">
 import {interfaceLanguage} from '$lib/i18n/context.svelte';const ui=interfaceLanguage();
 import {validateLocalization,type AdventureLocalization} from './adventure';import {languageName} from './locale';
 let {value,onchange}:{value?:AdventureLocalization;onchange:(value:AdventureLocalization)=>void}=$props();
 let customLang=$state(''),error=$state('');
 function addLanguage(){const locale=customLang.trim();try{const next={...configuration,locales:[...new Set([...configuration.locales,locale])]};validateLocalization(next);onchange(next);customLang='';error='';}catch{error='Usa un código de idioma como es, en o pt-BR.';}}
 const configuration=$derived(value??{defaultLocale:'es',locales:['es']});
 function toggle(locale:string,checked:boolean){const locales=checked?[...new Set([...configuration.locales,locale])]:configuration.locales.filter(l=>l!==locale);const translations=Object.fromEntries(Object.entries(configuration.translations??{}).filter(([locale])=>locales.includes(locale)));onchange({...configuration,locales,translations});}
</script>
<details class="adventure-languages"><summary>{ui.text("Idiomas de la aventura")} <small>{configuration.locales.map(languageName).join(' · ')}</small></summary><label>{ui.text("Idioma original")}<select aria-label={ui.text("Idioma original de la aventura")} value={configuration.defaultLocale} onchange={event=>onchange({...configuration,defaultLocale:event.currentTarget.value})}>{#each configuration.locales as locale}<option value={locale}>{languageName(locale)}</option>{/each}</select></label><div class="choices">{#each [...new Set(['es','en',...configuration.locales])] as locale}<label><input type="checkbox" checked={configuration.locales.includes(locale)} disabled={configuration.defaultLocale===locale||Object.keys(configuration.translations?.[locale]??{}).length>0} onchange={event=>toggle(locale,event.currentTarget.checked)}/>{languageName(locale)}</label>{/each}</div><div class="add-language"><input aria-label={ui.text("Nuevo idioma")} bind:value={customLang} placeholder={ui.text("en, fr…")}/><button type="button" aria-label={ui.text("Añadir idioma")} disabled={!customLang.trim()} onclick={addLanguage}>{ui.text("Añadir idioma")}</button></div>{#if error}<p role="alert">{ui.text(error)}</p>{/if}<p>{ui.text("El idioma original debe coincidir con el contenido existente. Los textos sin traducir conservan su versión original. Los módulos Info, Vídeo y Pregunta permiten editar sus textos por idioma.")}</p></details>
<style>.adventure-languages{border-top:1px solid #dce3d6;margin:16px 0;padding-top:12px}.adventure-languages summary{cursor:pointer;font-size:13px;font-weight:600}.adventure-languages summary small{display:block;color:#75836e;font-weight:400;margin-top:4px}.adventure-languages>label{display:block;margin-top:12px;font-size:12px}.adventure-languages select{width:100%;margin-top:5px;padding:8px;border:1px solid #dce3d6;border-radius:6px;background:white}.choices{display:flex;flex-wrap:wrap;gap:16px;margin-top:12px}.choices label{display:flex;align-items:center;gap:5px;font-size:12px}.adventure-languages p{font-size:11px;color:#75836e;line-height:1.5}.add-language{display:flex;gap:7px;margin-top:12px}.add-language input{min-width:0;flex:1;padding:8px;border:1px solid #dce3d6;border-radius:6px;background:white;font:inherit}.add-language button{padding:8px;border:1px solid #dce3d6;border-radius:6px;background:white;font:inherit;color:inherit;cursor:pointer;flex:none}.add-language button:disabled{opacity:.45}.add-language input:focus-visible,.add-language button:focus-visible{outline:2px solid #789557;outline-offset:2px}</style>
